import math
import re

from plugins import PluginError, Renderer, register

# Strings matching this pattern are safe to emit unquoted: they cannot be
# misread as numbers, booleans, nulls, or flow/sequence syntax.
_PLAIN = re.compile(r"^[A-Za-z_][A-Za-z0-9_\-./]*$")


def _escape(s: str) -> str:
    out = []
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        elif ord(ch) < 0x20 or ch == "\x7f":
            out.append(f"\\x{ord(ch):02x}")
        else:
            out.append(ch)
    return "".join(out)


def _string(s: str) -> str:
    if _PLAIN.match(s):
        return s
    return '"' + _escape(s) + '"'


def _scalar(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if math.isnan(value):
            return ".nan"
        if math.isinf(value):
            return ".inf" if value > 0 else "-.inf"
        return repr(value)
    if isinstance(value, str):
        return _string(value)
    raise PluginError(f"yaml cannot render value of type {type(value).__name__}")


def _key(k) -> str:
    if isinstance(k, str):
        return _string(k)
    return _scalar(k)


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for r in rows:
            if not r:
                lines.append("- {}")
                continue
            first = True
            for k, v in r.items():
                prefix = "- " if first else "  "
                lines.append(f"{prefix}{_key(k)}: {_scalar(v)}")
                first = False
        return "\n".join(lines) + "\n"

