"""YAML renderer. Standard library only -- see CONTRIBUTING.md."""

import math
import re

from plugins import PluginError, Renderer, register

# A string matching this can be emitted unquoted: it cannot be misread as a
# number, bool, null, or a mapping/sequence indicator.
_PLAIN_SAFE = re.compile(r"^[A-Za-z_][A-Za-z0-9_./-]*$")

# Words YAML would otherwise parse as bool/null even when quoted-looking.
_RESERVED = {"true", "false", "null", "yes", "no", "on", "off"}


def _scalar(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if math.isnan(value):
            return ".nan"
        if math.isinf(value):
            return ".inf" if value > 0 else "-.inf"
        return repr(value)
    if isinstance(value, str):
        if _PLAIN_SAFE.match(value) and value.lower() not in _RESERVED:
            return value
        return "'" + value.replace("'", "''") + "'"
    raise PluginError(f"yaml cannot render value of type {type(value).__name__}")


def _key(key) -> str:
    if isinstance(key, str):
        return _scalar(key)
    return _scalar(str(key))


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for row in rows:
            if not row:
                lines.append("- {}")
                continue
            items = [(_key(k), _scalar(v)) for k, v in row.items()]
            first_key, first_val = items[0]
            lines.append(f"- {first_key}: {first_val}")
            for k, v in items[1:]:
                lines.append(f"  {k}: {v}")
        return "\n".join(lines) + "\n"

