import math
import re

from plugins import PluginError, Renderer, register

# Strings that YAML would misread as non-string scalars if emitted plain.
_AMBIGUOUS = re.compile(
    r"""^(
        [-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?   # decimals, 1e3, .5
      | 0[xX][0-9a-fA-F]+                            # hex
      | 0[oO][0-7]+                                  # octal
      | [-+]?\.(?:inf|Inf|INF)                       # infinity
      | \.(?:nan|NaN|NAN)                            # nan
      | (?:true|True|TRUE|false|False|FALSE)         # booleans
      | (?:null|Null|NULL|~)                         # null
      | (?:yes|Yes|YES|no|No|NO|on|On|ON|off|Off|OFF) # YAML 1.1 booleans
    )$""",
    re.VERBOSE,
)

# Characters that make a string unsafe as a plain scalar at the start.
_LEADING_UNSAFE = "-?:,[]{}#&*!|>'\"%@`"


def _plain_ok(s: str) -> bool:
    """True if s can be emitted as a YAML plain scalar unchanged."""
    if not s or s != s.strip():
        return False
    if s[0] in _LEADING_UNSAFE:
        return False
    if ": " in s or " #" in s or s.endswith(":"):
        return False
    if any(ord(c) < 0x20 or ord(c) == 0x7F for c in s):
        return False
    if _AMBIGUOUS.match(s):
        return False
    return True


def _double_quote(s: str) -> str:
    """Emit s as a YAML double-quoted scalar."""
    out = []
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        elif ord(ch) < 0x20 or ord(ch) == 0x7F:
            out.append(f"\\x{ord(ch):02x}")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def _scalar(value) -> str:
    """Render one scalar value as a YAML scalar string."""
    if value is None:
        return "null"
    if isinstance(value, bool):  # before int: bool is a subclass of int
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if math.isnan(value):
            return ".nan"
        if math.isinf(value):
            return ".inf" if value > 0 else "-.inf"
        return repr(value)
    if isinstance(value, str):
        return value if _plain_ok(value) else _double_quote(value)
    raise PluginError(f"yaml cannot render value of type {type(value).__name__!r}")


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for r in rows:
            if not r:
                raise PluginError("yaml rows must be non-empty flat dicts")
            for i, (k, v) in enumerate(r.items()):
                if not isinstance(k, str):
                    raise PluginError(f"yaml keys must be strings, got {type(k).__name__!r}")
                prefix = "- " if i == 0 else "  "
                lines.append(f"{prefix}{_scalar(k)}: {_scalar(v)}")
        return "\n".join(lines) + "\n"

